<script>
  function updateUploadedFileInfo(input) {
    const previewBadge = document.getElementById('filePreviewBadge');
    const nameDisplay = document.getElementById('fileNameDisplay');
    const sizeDisplay = document.getElementById('fileSizeDisplay');
    
    if (input.files && input.files[0]) {
      const file = input.files[0];
      nameDisplay.innerText = file.name;
      const sizeMb = (file.size / (1024 * 1024)).toFixed(2);
      sizeDisplay.innerText = `(${sizeMb} MB)`;
      previewBadge.classList.remove('hidden');
      previewBadge.classList.add('inline-flex');
    }
  }

  function handleFormSubmit() {
    const nama = document.getElementById('namaLengkap').value;
    const wa = document.getElementById('noWhatsapp').value;
    const kampus = document.getElementById('asalKampus').value;
    const kategori = document.getElementById('kategoriCetak').value;
    const driveLink = document.getElementById('linkDrive').value;
    const catatan = document.getElementById('catatanKhusus').value;
    const fileUpload = document.getElementById('fileUpload').files[0];

    let fileNote = fileUpload ? `File Terunggah: ${fileUpload.name}` : (driveLink ? `Link Cloud: ${driveLink}` : 'File akan dikirim di chat ini');

    const pesan = `Halo printno.id, saya mau cetak pesanan kilat:%0A%0A` +
      `*Nama:* ${encodeURIComponent(nama)}%0A` +
      `*WhatsApp:* ${encodeURIComponent(wa)}%0A` +
      `*Kampus/Fakultas:* ${encodeURIComponent(kampus)}%0A` +
      `*Kategori Cetak:* ${encodeURIComponent(kategori)}%0A` +
      `*File/Link:* ${encodeURIComponent(fileNote)}%0A` +
      `*Catatan Khusus:* ${encodeURIComponent(catatan || '-')}%0A%0A` +
      `Mohon dibantu konfirmasi rincian biaya & estimasi waktu selesainya. Terima kasih!`;

    window.open(`https://wa.me/6281234567890?text=${pesan}`, '_blank');
  }

  function scrollToForm() {
    const formSection = document.getElementById('printForm');
    if (formSection) {
      formSection.scrollIntoView({ behavior: 'smooth', block: 'center' });
      document.getElementById('namaLengkap').focus();
    }
  }
</script></main>
